// include benchmark-specific definitions (NR, NQ, NP, etc.)
#include "doitgen.hpp"

using num_t = DATA_TYPE;

namespace {

// dimension prototypes
constexpr auto r_vec = noarr::vector<'r'>(); // corresponds to C index r (0..NR-1)
constexpr auto q_vec = noarr::vector<'q'>(); // corresponds to C index q (0..NQ-1)
constexpr auto p_vec = noarr::vector<'p'>(); // corresponds to C index p (0..NP-1)
constexpr auto s_vec = noarr::vector<'s'>(); // corresponds to C index s (0..NP-1)

// layouts (match C memory layout: last index varies fastest)
constexpr auto A_layout   = p_vec ^ q_vec ^ r_vec; // A[r][q][p]
constexpr auto C4_layout  = p_vec ^ s_vec;         // C4[s][p]
constexpr auto sum_layout = p_vec;                 // sum[p]

// initialization function
void init_array(auto A, auto C4) {
	using namespace noarr;

	// Precompute lengths once; they are constant for the whole initialization.
	const auto np_len_A  = A  | get_length<'p'>();
	const auto np_len_C4 = C4 | get_length<'p'>();

	// A[r][q][p] = ((r*q + p) % np) / np;
	traverser(A).for_each([=](auto state) {
		auto [r, q, p] = get_indices<'r', 'q', 'p'>(state);

		A[state] = static_cast<num_t>(( (r * q + p) % np_len_A ))
		           / static_cast<num_t>(np_len_A);
	});

	// C4[s][p] = (s*p % np) / np;
	traverser(C4).for_each([=](auto state) {
		auto [s, p] = get_indices<'s', 'p'>(state);

		C4[state] = static_cast<num_t>(( (s * p) % np_len_C4 ))
		            / static_cast<num_t>(np_len_C4);
	});
}

// computation kernel
//
// Original C kernel structure:
//
// for (r)
//   for (q) {
//     for (p) {
//       sum[p] = 0;
//       for (s)
//         sum[p] += A[r][q][s] * C4[s][p];
//     }
//     for (p)
//       A[r][q][p] = sum[p];
//   }
//
// The optimized version below keeps the same mathematical computation,
// but uses a more cache‑friendly and load‑efficient ordering:
//
//   for (r)
//     for (q) {
//       for (p) sum[p] = 0;
//       for (s) {
//         a_rqs = A[r][q][s];
//         for (p)
//           sum[p] += a_rqs * C4[s][p];
//       }
//       for (p) A[r][q][p] = sum[p];
//     }
//
// For each fixed p, the accumulation over s still happens in the same
// s-order as in the original code; only independent work across p is
// interleaved. This preserves per‑p floating‑point accumulation order
// while:
//
//   - loading A[r][q][s] only once per (r,q,s) and reusing it for all p
//   - walking C4 row-wise (s outer, p inner) so its accesses are
//     contiguous in memory
//   - keeping all loop nests expressed via Noarr traversers.
//
[[gnu::flatten, gnu::noinline]]
void kernel_doitgen(auto A, auto C4, auto sum) {
	using namespace noarr;

	// Traverser for (C4, sum) reused for every (r, q) pair.
	auto trav_C4_sum = traverser(C4, sum);

#pragma scop
	traverser(A, sum).template for_dims<'r', 'q'>([&](auto trav_rq) {

		// Fixed indices r and q for this slice of A.
		auto rq_state = trav_rq.state();
		auto r_idx = get_index<'r'>(rq_state);
		auto q_idx = get_index<'q'>(rq_state);

		// --------------------------------------------------------------
		// Phase 1: clear the temporary accumulation buffer sum[p]
		//          for the current (r, q).
		// --------------------------------------------------------------
		trav_rq.for_each([&](auto state_rqp) {
			// state_rqp contains {r, q, p}, but sum only uses 'p'.
			sum[state_rqp] = static_cast<num_t>(0);
		});

		// --------------------------------------------------------------
		// Phase 2: perform the matrix–vector like product
		//
		//   for (s)
		//     a_rqs = A[r][q][s];
		//     for (p)
		//       sum[p] += a_rqs * C4[s][p];
		//
		// We iterate 's' with trav_C4_sum.for_dims<'s'>, and then
		// iterate 'p' inside trav_s.for_each(). For each fixed 's'
		// we:
		//   - load A[r][q][s] exactly once, and
		//   - scan C4[s][p] and sum[p] with contiguous 'p' access.
		// --------------------------------------------------------------
		trav_C4_sum.template for_dims<'s'>([&](auto trav_s) {
			// s index for this row of C4 and this contribution from A.
			auto s_state = trav_s.state();
			auto s_idx = get_index<'s'>(s_state);

			// Load once per (r, q, s) and reuse across all p.
			const num_t a_rqs =
				A[noarr::idx<'r', 'q', 'p'>(r_idx, q_idx, s_idx)];

			// For fixed s, iterate over p (shared between C4 and sum).
			trav_s.for_each([&](auto sp_state) {
				// sp_state contains {s, p}; sum ignores 's' and uses only 'p'.
				sum[sp_state] += a_rqs * C4[sp_state];
			});
		});

		// --------------------------------------------------------------
		// Phase 3: write back the accumulated values:
		//          A[r][q][p] = sum[p] for all p.
		// --------------------------------------------------------------
		trav_rq.for_each([&](auto state_rqp) {
			A[state_rqp] = sum[state_rqp];
		});
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t nr = NR;
	std::size_t nq = NQ;
	std::size_t np = NP;

