		auto state_rq = trav_rq.state();
		auto r_idx = get_index<'r'>(state_rq);
		auto q_idx = get_index<'q'>(state_rq);

		// ---------------------------------------------------------------------
		// 1) Initialize sum[p] = 0 for all p
		// ---------------------------------------------------------------------
		traverser(sum).for_each([&](auto state_p) {
			sum[state_p] = static_cast<num_t>(0);
		});

		// ---------------------------------------------------------------------
		// 2) Accumulate sum[p] += A[r][q][s] * C4[s][p]
		//
		// We use the 'p' dimension of A as the s-loop (s is just a loop
		// variable name here). For each s we:
		//   - read A[r][q][s] once (contiguous access across s),
		//   - take the s-th row of C4 (C4[s][p]) via fix<'s'>(s),
		//   - traverse p as the innermost loop to walk that row contiguously,
		//     accumulating into sum[p].
		// ---------------------------------------------------------------------
		trav_rq.template for_dims<'p'>([&](auto trav_rqs) {
			// r, q fixed; 'p' here plays the role of s
			auto state_rqs = trav_rqs.state();
			auto s_idx = get_index<'p'>(state_rqs); // index along A's third dim

			// A[r][q][s] - read once per s
