				auto state_p = trav_p.state(); // contains index p

				sum[state_p] += a_rqs * C4_row[state_p];
			});
		});

		// ---------------------------------------------------------------------
		// 3) Write back: A[r][q][p] = sum[p]
		//
		// We now copy the accumulated sums for this (r,q) into A.
		// ---------------------------------------------------------------------
		traverser(sum).for_each([&](auto state_p) {
			auto p_idx = get_index<'p'>(state_p);
			auto state_rqp = idx<'r', 'q', 'p'>(r_idx, q_idx, p_idx);
			A[state_rqp] = sum[state_p];
		});
