/*
 * Optimized computation kernel
 *
 * Original C-like kernel:
 *
 * for (r)
 *   for (q) {
 *     for (p) {
 *       sum[p] = 0;
 *       for (s)
 *         sum[p] += A[r][q][s] * C4[s][p];
 *     }
 *     for (p)
 *       A[r][q][p] = sum[p];
 *   }
 *
 * Mathematically this computes, for each fixed (r,q):
 *   A_out[r][q][p] = Σ_s A_in[r][q][s] * C4[s][p]
 *
 * The computation over p and s is independent per (r,q),
 * so we can legally reorder the p/s loops as:
 *
 *   // for each (r,q)
 *   sum[:] = 0
 *   for (s)
 *     for (p)
 *       sum[p] += A[r][q][s] * C4[s][p];
 *   for (p)
 *     A[r][q][p] = sum[p];
 *
 * This improves data locality significantly:
 *   - Each A[r][q][s] is loaded once per (r,q) and reused
 *   - C4[s][p] is accessed consecutively along p
 *   - sum[p] is updated in a tight, vectorizable inner loop
 *
 * All loops are expressed via Noarr traversers as required.
 */
[[gnu::flatten, gnu::noinline]]
void kernel_doitgen(auto A, auto C4, auto sum) {
	using namespace noarr;

#pragma scop
	// Outer loops over r and q (corresponds to C: for (r) for (q))
	traverser(A).template for_dims<'r', 'q'>([=](auto trav_rq) {

		// Extract the fixed r, q indices for this tile
		auto state_rq = trav_rq.state(); // contains 'r' and 'q'
		auto r_idx    = get_index<'r'>(state_rq);
		auto q_idx    = get_index<'q'>(state_rq);

		// --------------------------------------------------------------------
		// 1) Initialize sum[p] = 0 for all p
		//
		// sum has only dimension 'p'; the indices 'r' and 'q' in state_rq
		// are *not* part of sum, so sum[p] is effectively shared across
		// all (r,q), and we reinitialize it for every (r,q) pair.
		// --------------------------------------------------------------------
		traverser(sum).for_each([&](auto state_p) {
			sum[state_p] = static_cast<num_t>(0);
		});

		// --------------------------------------------------------------------
		// 2) Accumulate over s, then over p:
		//
		//    for (s)
		//      for (p)
		//        sum[p] += A[r][q][s] * C4[s][p];
		//
		// We drive the loops using traverser(C4):
		//  - outer for_dims<'s'>  iterates rows of C4
		//  - inner for_dims<'p'>  iterates columns (contiguous in memory)
		//
		// For A we use the same s index, but mapped onto its 'p' dimension:
		//    A[r][q][s] == A at indices (r, q, p = s)
		// --------------------------------------------------------------------
		traverser(C4).template for_dims<'s'>([&](auto trav_s) {
			// Fixed s for this row of C4
			auto state_s = trav_s.state(); // contains 's'
			auto s_idx   = get_index<'s'>(state_s);

			// Load A[r][q][s] once per (r, q, s) and reuse across all p
			auto state_rqs = idx<'r', 'q', 'p'>(r_idx, q_idx, s_idx);
			num_t a_rqs    = A[state_rqs];

			// Now iterate over p for this fixed s (row of C4)
			trav_s.template for_dims<'p'>([&](auto trav_sp) {
				auto state_sp = trav_sp.state(); // contains 's' and 'p'

				// sum[p] += A[r][q][s] * C4[s][p]
				//
				// state_sp carries both 's' and 'p', but sum only has 'p',
				// so the 's' component is ignored when indexing sum.
				sum[state_sp] += a_rqs * C4[state_sp];
			});
		});

		// --------------------------------------------------------------------
		// 3) Write back result:
		//
		//    for (p)
		//      A[r][q][p] = sum[p];
		//
		// We reuse trav_rq and iterate dimension 'p' inside it.
		// --------------------------------------------------------------------
		trav_rq.template for_dims<'p'>([&](auto trav_rqp) {
			auto state_rqp = trav_rqp.state(); // contains 'r', 'q', 'p'

			// sum ignores 'r' and 'q', using only 'p'
			A[state_rqp] = sum[state_rqp];
		});
	});
#pragma endscop
}

