using num_t = DATA_TYPE;

namespace {

// dimension prototypes
constexpr auto r_vec = noarr::vector<'r'>(); // corresponds to C index r (0..NR-1)
constexpr auto q_vec = noarr::vector<'q'>(); // corresponds to C index q (0..NQ-1)
constexpr auto p_vec = noarr::vector<'p'>(); // corresponds to C index p (0..NP-1)
constexpr auto s_vec = noarr::vector<'s'>(); // corresponds to C index s (0..NP-1)

// layouts (match C memory layout: last index varies fastest)
constexpr auto A_layout   = p_vec ^ q_vec ^ r_vec; // A[r][q][p]
constexpr auto C4_layout  = p_vec ^ s_vec;         // C4[s][p]
constexpr auto sum_layout = p_vec;                 // sum[p]

// initialization function
void init_array(auto A, auto C4) {
	using namespace noarr;

	// cache lengths once instead of querying them in every iteration
	const std::size_t np_len_A  = A  | get_length<'p'>();
	const std::size_t np_len_C4 = C4 | get_length<'p'>();

	// A[r][q][p] = ((r*q + p) % np) / np;
	traverser(A).for_each([&](auto state) {
		auto [r, q, p] = get_indices<'r', 'q', 'p'>(state);

		A[state] = static_cast<num_t>(((r * q + p) % np_len_A))
			/ static_cast<num_t>(np_len_A);
	});

	// C4[s][p] = (s*p % np) / np;
	traverser(C4).for_each([&](auto state) {
		auto [s, p] = get_indices<'s', 'p'>(state);

		C4[state] = static_cast<num_t>(((s * p) % np_len_C4))
			/ static_cast<num_t>(np_len_C4);
	});
}

// computation kernel
//
// Original C kernel for reference:
//
// for (r)
//   for (q) {
//     for (p) {
//       sum[p] = 0;
//       for (s)
//         sum[p] += A[r][q][s] * C4[s][p];
//     }
//     for (p)
//       A[r][q][p] = sum[p];
//   }
//
// Optimized scheme (for each fixed r,q):
//
// 1) for (p) sum[p] = 0;
// 2) for (s) {
//      const a = A[r][q][s];
//      for (p) sum[p] += a * C4[s][p];
//    }
// 3) for (p) A[r][q][p] = sum[p];
//
// This changes loop nesting from r,q,p,s to r,q,s,p while keeping, for each p,
// the sequence of additions over s in the same order. Thus floating‑point
// accumulation order per element is preserved, but we exploit much better data
// locality: A[r][q][s] is reused across all p, and C4[s][p] is accessed with p
// as the inner (contiguous) dimension.
[[gnu::flatten, gnu::noinline]]
void kernel_doitgen(auto A, auto C4, auto sum) {
	using namespace noarr;

#pragma scop
	// Outer loops: iterate over (r, q)
	traverser(A, sum).template for_dims<'r', 'q'>([&](auto trav_rq) {

		// Extract (r, q) indices once for this tile
		auto rq_state = trav_rq.state(); // contains 'r', 'q'
		const std::size_t r_idx = get_index<'r'>(rq_state);
		const std::size_t q_idx = get_index<'q'>(rq_state);

		// ---------------------------------------------------------------------
		// 1) Zero the temporary vector sum[p] for this (r, q)
		// ---------------------------------------------------------------------
		traverser(sum).for_each([&](auto state_p) {
			// state_p contains only 'p'
			sum[state_p] = static_cast<num_t>(0);
		});

		// ---------------------------------------------------------------------
		// 2) Accumulate over s, updating all p at once for each s
		//    sum[p] += A[r][q][s] * C4[s][p]
		// ---------------------------------------------------------------------
		traverser(C4).template for_dims<'s'>([&](auto trav_s) {
			// trav_s has 's' fixed, remaining dimension is 'p'
			auto s_state = trav_s.state(); // contains 's'
			const std::size_t s_idx = get_index<'s'>(s_state);

			// Load A[r][q][s] once and reuse it for all p
			auto a_state = idx<'r', 'q', 'p'>(r_idx, q_idx, s_idx);
			const num_t a_val = A[a_state];

			// For this s, walk all p (inner-most, contiguous in memory for C4)
			trav_s.for_each([&](auto sp_state) {
				// sp_state contains 's' and 'p'
				// - C4[sp_state] uses both 's' and 'p' -> C4[s][p]
				// - sum[sp_state] ignores 's', uses only 'p' -> sum[p]
				sum[sp_state] += a_val * C4[sp_state];
			});
		});

		// ---------------------------------------------------------------------
		// 3) Write back: A[r][q][p] = sum[p]
		// ---------------------------------------------------------------------
		trav_rq.template for_dims<'p'>([&](auto trav_rqp) {
			auto state_rqp = trav_rqp.state(); // contains 'r', 'q', 'p'

			// sum[state_rqp] ignores 'r' and 'q', using only 'p'
			A[state_rqp] = sum[state_rqp];
		});
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t nr = NR;
	std::size_t nq = NQ;
	std::size_t np = NP;

	// allocate data (bags)
	auto A = noarr::make_bag(
		noarr::scalar<num_t>()
		^ A_layout
		^ noarr::set_length<'r'>(nr)
		^ noarr::set_length<'q'>(nq)
		^ noarr::set_length<'p'>(np));

	auto C4 = noarr::make_bag(
		noarr::scalar<num_t>()
		^ C4_layout
		^ noarr::set_length<'s'>(np)
		^ noarr::set_length<'p'>(np));

	auto sum = noarr::make_bag(
		noarr::scalar<num_t>()
		^ sum_layout
		^ noarr::set_length<'p'>(np));

	// initialize arrays
	init_array(A.get_ref(), C4.get_ref());

	// start timer
	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_doitgen(A.get_ref(), C4.get_ref(), sum.get_ref());

	// stop timer
	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// optionally print output (to prevent DCE and to check correctness)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		// hoist 'r' for a more natural outer dimension in the dump
		noarr::serialize_data(std::cerr, A.get_ref() ^ noarr::hoist<'r'>());
	}

	// print elapsed time in seconds
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
